    func feedback(_ score: Int, _ pass: Int) -> String {
        if score >= max(90, pass) { return t("Wonderful! 🌟", "அருமை! 🌟", "ಅದ್ಭುತ! 🌟", "बहुत सुंदर! 🌟", "అద్భుతం! 🌟", "अद्भुतम्! 🌟") }
        if score >= pass { return t("Good! 👏 Red and orange words need a little more practice.", "நன்று! 👏 சிவப்புச் சொற்களை இன்னும் பயிலுங்கள்.", "ಚೆನ್ನಾಗಿದೆ! 👏 ಕೆಂಪು ಪದಗಳನ್ನು ಇನ್ನಷ್ಟು ಅಭ್ಯಾಸ ಮಾಡಿ.", "अच्छा! 👏 लाल शब्दों का थोड़ा और अभ्यास करें।", "బాగుంది! 👏 ఎరుపు పదాలు ఇంకొంచెం అభ్యసించండి.", "साधु! 👏 रक्तानि नारङ्गवर्णानि च पदानि किञ्चिद् अधिकम् अभ्यस।") }
        if score >= 40 { return t("Almost there 💪 Tap the red words to hear them.", "கிட்டத்தட்ட 💪 சிவப்புச் சொற்களைத் தொட்டுக் கேளுங்கள்.", "ಹತ್ತಿರ ಬಂದಿದ್ದೀರಿ 💪 ಕೆಂಪು ಪದ ಒತ್ತಿ ಕೇಳಿ.", "लगभग 💪 लाल शब्द छूकर सुनें।", "దగ్గరకు వచ్చారు 💪 ఎరుపు పదాలు తాకి వినండి.", "प्रायः सिद्धम् 💪 रक्तपदानि स्पृष्ट्वा शृणु।") }
        return t("Let's listen once more 🎧 and try again.", "இன்னொரு முறை கேட்டு 🎧 மீண்டும் முயல்வோம்.", "ಇನ್ನೊಮ್ಮೆ ಕೇಳಿ 🎧 ಮತ್ತೆ ಪ್ರಯತ್ನಿಸೋಣ.", "एक बार और सुनें 🎧 फिर कोशिश करें।", "మరోసారి విని 🎧 మళ్ళీ ప్రయత్నిద్దాం.", "पुनरेकवारं शृणुमः 🎧 पुनः प्रयतामहे च।")
    }
