    func updatesBody(_ text: Bool, _ packs: [Int]) -> String {
        var parts: [String] = []
        if text { parts.append(t("corrected text", "திருத்திய நூல்", "ತಿದ್ದಿದ ಪಠ್ಯ", "सुधरा पाठ्य", "సరిచేసిన పాఠం", "शोधितः पाठः")) }
        if !packs.isEmpty { parts.append(t("better chant for sandhi ", "சந்தி பாராயணம் மேம்பட்டது: ", "ಉತ್ತಮ ಪಠಣ, ಸಂಧಿ ", "बेहतर पाठ, संधि ", "మెరుగైన పఠనం, సంధి ", "उत्तमः पाठः, सन्धिः ") + packs.map(String.init).joined(separator: ", ")) }
        return parts.joined(separator: " · ")
    }
    func badgeTitle(_ id: String) -> String { badgeText[id]?.0 ?? id }
    func badgeHint(_ id: String) -> String { badgeText[id]?.1 ?? "" }
    func strictName(_ s: Strictness) -> String { switch s { case .gentle: strictGentle; case .normal: strictNormal; case .strict: strictStrict } }
    func strictSub(_ s: Strictness) -> String { switch s { case .gentle: strictGentleSub; case .normal: strictNormalSub; case .strict: strictStrictSub } }
